// Memory exact-duplicate sweep.
// Removes byte-identical memories (same project + content) keeping the richest
// copy, then prunes links orphaned by those deletes. Defense-in-depth behind
// the deterministic-id fix in flush_insights.py (which prevents new exact dupes).
const QDRANT_URL = 'http://qdrant:6333';
const QDRANT_API_KEY = $env.QDRANT_API_KEY || '';
const COLLECTIONS = ['claude_memories', 'memories_warm', 'memories_hot'];
// types that must never be deleted even if duplicated
const PROTECTED_TYPES = new Set(['procedure', 'learning', 'trajectory']);

async function scrollAll(collection) {
  let out = [], offset = null;
  while (true) {
    const body = { limit: 1000, with_payload: true, with_vector: false };
    if (offset) body.offset = offset;
    const d = await helpers.httpRequest({
      method: 'POST',
      headers: { 'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      url: `${QDRANT_URL}/collections/${collection}/points/scroll`,
      json: true,
    });
    const res = d.result || {};
    out = out.concat(res.points || []);
    offset = res.next_page_offset;
    if (!offset) break;
  }
  return out;
}

async function deleteIds(collection, ids) {
  // wait=true: force synchronous application; 'acknowledged' deletes can be
  // dropped silently (2026-07-03 incident: sweep reported 20k deleted, ~6k applied)
  for (let i = 0; i < ids.length; i += 500) {
    const chunk = ids.slice(i, i + 500).map(String);
    const res = await helpers.httpRequest({
      method: 'POST',
      headers: { 'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({ points: chunk }),
      url: `${QDRANT_URL}/collections/${collection}/points/delete?wait=true`,
      json: true,
    });
    const st = res && res.result && res.result.status;
    if (st !== 'completed') throw new Error(`delete batch not completed (status=${st})`);
  }
}

async function exactCount(collection) {
  const d = await helpers.httpRequest({
    method: 'POST',
    headers: { 'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ exact: true }),
    url: `${QDRANT_URL}/collections/${collection}/points/count`,
    json: true,
  });
  return d.result.count;
}

// rank tuple: higher is better (pinned, verified, more tags, newer)
function rank(pl) {
  return [pl.pinned ? 1 : 0, pl.last_verified_date || '', (pl.tags || []).length, pl.created_at || ''];
}
function cmpDesc(a, b) {
  const ra = rank(a.payload || {}), rb = rank(b.payload || {});
  for (let i = 0; i < ra.length; i++) {
    if (ra[i] < rb[i]) return 1;
    if (ra[i] > rb[i]) return -1;
  }
  return String(a.id) < String(b.id) ? 1 : -1;
}

const summary = { ts: new Date().toISOString(), deleted: {}, links_deleted: 0, errors: [] };
const deletedAll = new Set();

for (const coll of COLLECTIONS) {
  try {
    const pts = await scrollAll(coll);
    const groups = new Map();
    for (const p of pts) {
      const pl = p.payload || {};
      const content = pl.content || pl.text || '';
      if (!content) continue; // never collapse empty-content rows
      const key = (pl.project || '(none)') + '\u0000' + content;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(p);
    }
    const del = [];
    for (const members of groups.values()) {
      if (members.length <= 1) continue;
      members.sort(cmpDesc); // best first
      for (let i = 1; i < members.length; i++) {
        const pl = members[i].payload || {};
        if (pl.pinned) continue;
        if (PROTECTED_TYPES.has(pl.type)) continue;
        del.push(members[i].id);
      }
    }
    const before = await exactCount(coll);
    if (del.length) await deleteIds(coll, del);
    del.forEach((id) => deletedAll.add(String(id)));
    const after = await exactCount(coll);
    // report VERIFIED deletions, not intended ones; flag any shortfall
    summary.deleted[coll] = before - after;
    if (before - after !== del.length) {
      summary.errors.push(`${coll}: intended ${del.length} deletes but count only dropped ${before - after}`);
    }
  } catch (e) {
    summary.errors.push(`${coll}: ${e.message}`);
  }
}

// Prune links orphaned by this run's deletions (keeps the knowledge graph clean).
try {
  if (deletedAll.size) {
    const links = await scrollAll('memory_links');
    const orphan = links
      .filter((l) => {
        const pl = l.payload || {};
        return deletedAll.has(String(pl.source_id)) || deletedAll.has(String(pl.target_id));
      })
      .map((l) => l.id);
    if (orphan.length) await deleteIds('memory_links', orphan);
    summary.links_deleted = orphan.length;
  }
} catch (e) {
  summary.errors.push(`memory_links: ${e.message}`);
}

return [{ json: summary }];
